        AND audit_admin_id = #{adminId,typeHandler=org.project.util.UUIDBinaryTypeHandler}


        AND audit_action = #{action}


        AND audit_resource = #{resource}


        AND audit_status = #{status}


        AND audit_created_at >= #{startDate}


        AND audit_created_at <= #{endDate}


ORDER BY audit_created_at DESC
LIMIT #{limit} OFFSET #{offset};

SELECT COUNT(*) FROM pcd_admin_audit_log_table


        AND audit_admin_id = #{adminId,typeHandler=org.project.util.UUIDBinaryTypeHandler}


        AND audit_action = #{action}


        AND audit_resource = #{resource}


        AND audit_status = #{status}


        AND audit_created_at >= #{startDate}


        AND audit_created_at <= #{endDate}

;
